INSERT INTO "Artist" (id, name, genres, "instagramUrl", bio, "createdAt", "updatedAt") VALUES
  ('f5b91994-ce70-430c-b5c4-d59659e2f502', 'Chico Amaral', 'jazz, MPB instrumental', 'https://instagram.com/chicoamaralsax', 'Saxofonista e ex-letrista do Skank. Residente do Quintajazz no Jângal toda quinta-feira. Álbum Canções Brasileiras (2024).', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('c07a406b-1ce6-4028-919b-6cf961aba1a0', 'Antonio Loureiro', 'jazz, MPB instrumental', 'https://instagram.com/antonioloureiromusic', 'Multi-instrumentista (vibrafone, piano, bateria, voz). Formado na UFMG, com álbuns internacionais.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('919dd488-ccf4-472a-8723-2c0f6a5ce187', 'Felipe Continentino', 'jazz contemporâneo', NULL, 'Baterista. Múltiplo vencedor do BDMG Instrumental (2014, 2017, 2019, 2021).', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('a5b22a9f-945e-4bdc-9e25-23dc3e3a3032', 'Toninho Horta', 'jazz fusion, bossa nova, MPB', NULL, 'Lenda da música brasileira. Guitarrista do Clube da Esquina. Mais de 50 anos de carreira.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('820f6b06-d318-4618-b79a-c19beaa97220', 'Carolina Serdeira', 'samba-jazz, MPB', NULL, 'Cantora e diretora artística do Jazz Brasil Festival. 18 anos de carreira.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('f9c54984-37a8-411b-b803-332d1218faca', 'Izzy Gordon', 'jazz, blues, funk, soul', 'https://instagram.com/izzygordon', 'Sobrinha de Dolores Duran. Show tributo Ella e Dolores.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('5aa56a87-f97b-4424-9f69-ced2c500c14c', 'Tamara Franklin', 'jazz, samba, afrobrasileiro', 'https://instagram.com/tamara_franklinn', 'Cantora que une jazz, RAP, samba e musicalidade afrobrasileira.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('6d8a207a-ea43-44b2-9794-216a25d8fdfa', 'Jamba Trio', 'jazz, bossa nova', NULL, 'Fundado em 1995. Um dos conjuntos de jazz mais sólidos de BH, com 25+ anos.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('1a84e587-cb95-4ca4-adf3-1f551511a9ba', 'Fred Selva Trio', 'jazz contemporâneo', NULL, 'Trio instrumental expoente da cena mineira.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('96bc4d48-dbe9-4cfa-b3b3-b26e56957667', 'Vinícius Mendes', 'jazz contemporâneo, free jazz', 'https://instagram.com/vinicius_mendes_rodrigues', 'Saxofonista formado na UFMG. Lançamentos pelo selo alemão Notes on a Journey.', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000');
