  ('ff4e6aad-1844-4188-84cd-e8c8f43ce8df', 'Sábado Blues – Clube de Jazz', 'Curadoria especial de blues. Músicos da cena mineira dedicados ao blues e suas conexões com o jazz.', '2026-05-11 21:30:00.000', '4e4df0bd-6607-497a-b56d-0be8e5ea1874', 25, 40, 'https://bileto.sympla.com.br/clubedejazzdocafecomletras', 'https://clubedejazzdocafe.com', 91, 'published', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('0672bf39-18e7-4dce-aadd-3db29db9411c', 'Carolina Serdeira – Samba-Jazz', 'Diretora artística do Jazz Brasil Festival, 18 anos de carreira. Voz marcante e música brasileira instrumental.', '2026-05-18 21:00:00.000', '4e4df0bd-6607-497a-b56d-0be8e5ea1874', 35, 55, 'https://bileto.sympla.com.br/clubedejazzdocafecomletras', 'https://clubedejazzdocafe.com', 95, 'published', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('ea06daa1-5b87-4b89-9bf1-b87b23b9afff', 'Antonio Loureiro – Show Solo', 'Multi-instrumentista mineiro: vibrafone, piano e voz. Carreira internacional reconhecida.', '2026-05-25 21:00:00.000', '4e4df0bd-6607-497a-b56d-0be8e5ea1874', 45, 70, 'https://bileto.sympla.com.br/clubedejazzdocafecomletras', 'https://clubedejazzdocafe.com', 97, 'published', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
