INSERT INTO "Post" (id, title, body, type, "publishedAt", "createdAt", "updatedAt") VALUES
  ('6e1bbb18-5e33-47ba-a73e-6086798d942b', 'Savassi Festival 2026: programação da 24ª edição começa em 24 de maio', 'O Savassi Festival confirma sua 24ª edição entre 24 e 31 de maio de 2026. Com programação em 8 espaços da Savassi — Clube de Jazz do Café com Letras, Café com Letras, Ototoi, Livraria da Rua, Conservatório UFMG e praças ao ar livre —, o festival reúne artistas nacionais e internacionais. Entrada gratuita na maioria das atrações.', 'announcement', '2026-05-05 12:00:00.000', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('1065b1e8-ffba-428a-a021-6e123561b9f4', 'Clube de Jazz do Café com Letras: o coração do jazz em BH', 'Inaugurado em 2022 pelo produtor Bruno Golgher, o Clube de Jazz é o espaço mais dedicado ao jazz em BH. Na Rua Antônio de Albuquerque, 47, funciona 6 noites por semana com 100 lugares. Jazz às sextas e sábados, blues aos sábados. Já tem 53 mil seguidores (@clubedejazzdocafe).', 'news', '2026-05-01 12:00:00.000', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('1c98d03d-e2fd-4947-9f20-ffbc92077f77', 'Mina Jazz Bar: jazz sofisticado no Centro histórico de BH', 'No antigo Salão de Música do Automóvel Clube de Minas (edificação tombada do séc. XX), o Mina Jazz Bar combina shows diários, coquetelaria elaborada e ambiente vintage. Fundado por Gabriel Azevedo e Léo Paixão. 102 mil seguidores (@minajazzbar).', 'news', '2026-05-03 12:00:00.000', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('770d856a-be84-491e-8320-fa9e61b94d3d', 'Chico Amaral: do Skank ao jazz – a reinvenção de um letrista', 'Ex-letrista do Skank, Chico Amaral revelou ao mundo do jazz um saxofonista completo. Seu álbum Canções Brasileiras (2024) é um dos trabalhos mais celebrados da música instrumental mineira. Toda quinta comanda o Quintajazz no Jângal, gratuito. (@chicoamaralsax)', 'interview', '2026-04-28 12:00:00.000', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000'),
  ('e1f4191a-3cdf-483e-a85d-0c3d461452ee', 'Guia: onde ouvir jazz em BH em 2026', 'BH tem hoje mais de uma dezena de espaços com jazz ao vivo regular. Destaques: Clube de Jazz do Café com Letras (6 noites/semana), Mina Jazz Bar (qua–sáb), Jângal Quintajazz (toda quinta, gratuito), Baretto Fasano (qui–sáb), Soul Jazz Burger (Santa Tereza e Pampulha). Festivais: Savassi Festival (mai/jun), Tudo é Jazz (jul), Jazz Brasil Festival (set).', 'news', '2026-05-07 12:00:00.000', '2026-05-08 12:00:00.000', '2026-05-08 12:00:00.000');
